using System.Text;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.EntityFrameworkCore;using Microsoft.IdentityModel.Tokens;using Microsoft.OpenApi.Models;using StudentCenter.ApplicationService.Application.Interfaces;using StudentCenter.ApplicationService.Application.Services;using StudentCenter.ApplicationService.Infrastructure.Persistence;using StudentCenter.ApplicationService.Infrastructure.Repositories;
var b=WebApplication.CreateBuilder(args);b.Services.AddControllers();b.Services.AddEndpointsApiExplorer();b.Services.AddSwaggerGen(o=>{o.AddSecurityDefinition("Bearer",new OpenApiSecurityScheme{Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new OpenApiSecurityRequirement{{new OpenApiSecurityScheme{Reference=new OpenApiReference{Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});});var cs=b.Configuration.GetConnectionString("ApplicationDb")!;var j=b.Configuration.GetSection("Jwt");var key=j["Key"]!;b.Services.AddDbContext<ApplicationDbContext>(o=>o.UseSqlServer(cs));b.Services.AddScoped<ICompetitionRepository,CompetitionRepository>();b.Services.AddScoped<CompetitionService>();b.Services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new TokenValidationParameters{ValidateIssuer=true,ValidIssuer=j["Issuer"],ValidateAudience=true,ValidAudience=j["Audience"],ValidateIssuerSigningKey=true,IssuerSigningKey=new SymmetricSecurityKey(Encoding.UTF8.GetBytes(key)),ValidateLifetime=true});b.Services.AddAuthorization(o=>o.AddPolicy("ManageApplications",p=>p.RequireClaim("permission","ManageApplications")));var app=b.Build();using(var scope=app.Services.CreateScope()){var db=scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();await db.Database.MigrateAsync();}if(app.Environment.IsDevelopment()){app.UseSwagger();app.UseSwaggerUI();}app.UseAuthentication();app.UseAuthorization();app.MapControllers();app.Run();
